package com.codegym.dao;
import com.codegym.model.User; import java.sql.*; import java.util.*;
public class UserDAO { private static final String URL="jdbc:mysql://localhost:3306/user_management?useSSL=false&serverTimezone=UTC"; private static final String USER="root"; private static final String PASSWORD=""; static { try{Class.forName("com.mysql.cj.jdbc.Driver");}catch(ClassNotFoundException e){throw new ExceptionInInitializerError(e);} } private Connection connect() throws SQLException{return DriverManager.getConnection(URL,USER,PASSWORD);} public List<User> selectUsers(String country,String sort) throws SQLException {String sql="SELECT id,name,email,country FROM users WHERE country LIKE ? ORDER BY name "+("desc".equalsIgnoreCase(sort)?"DESC":"ASC"); List<User> result=new ArrayList<>(); try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,"%"+(country==null?"":country.trim())+"%");try(ResultSet r=p.executeQuery()){while(r.next())result.add(new User(r.getInt("id"),r.getString("name"),r.getString("email"),r.getString("country")));}}return result;} public User findById(int id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT id,name,email,country FROM users WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?new User(r.getInt("id"),r.getString("name"),r.getString("email"),r.getString("country")):null;}}} public void insert(User u)throws SQLException{execute("INSERT INTO users(name,email,country) VALUES(?,?,?)",u,false);} public void update(User u)throws SQLException{execute("UPDATE users SET name=?,email=?,country=? WHERE id=?",u,true);} public void delete(int id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM users WHERE id=?")){p.setInt(1,id);p.executeUpdate();}} private void execute(String sql,User u,boolean update)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,u.getName());p.setString(2,u.getEmail());p.setString(3,u.getCountry());if(update)p.setInt(4,u.getId());p.executeUpdate();}} }
